-- StarUniv 최종 Supabase 통합 설정
-- 최종 적용에서는 이 파일 하나만 Supabase SQL Editor에서 실행하세요.
-- 재실행 가능한 DDL/정책과 충돌 안전한 시드(upsert/do nothing)로 구성되어 있습니다.


-- ============================================================================
-- 기본 스키마
-- ============================================================================

-- StarUniv Supabase schema
-- 1) Supabase SQL Editor에서 이 파일 전체를 실행합니다.
-- 2) 현재 사이트는 DB를 브라우저에서 직접 읽지 않고 GitHub Actions가 db.json으로 내보냅니다.
--    그래서 RLS는 켜되 공개 정책은 만들지 않습니다.

create table if not exists public.settings (
  source_order integer primary key,
  season text not null,
  start_date date
);

create table if not exists public.teams (
  id bigint generated by default as identity primary key,
  source_order integer not null unique,
  team_name text not null,
  founders text,
  founded_date date,
  disbanded_date date,
  note text,
  championship text,
  logo_path text
);
create index if not exists teams_team_name_idx on public.teams (team_name);

create table if not exists public.members (
  -- StarUniv 내부 행 식별자. 외부 서비스 ID와 절대 혼용하지 않는다.
  id bigint generated by default as identity primary key,
  source_order integer not null unique,
  -- 같은 사람의 기준 이름. 예: 진땅콩
  name text not null,
  -- 해당 멤버 행에서 실제 사용한 표시/방송 닉네임. 예: 진땅콩 T
  nickname text not null,
  -- SOOP 계정 ID
  soop_id text,
  -- ELO보드 선수 ID. ELO 원본 players 객체의 key(id)를 여기에는 elo_id로 저장한다.
  elo_id integer,
  birth_date date,
  gender text,
  race text,
  join_tier text,
  tier text,
  role text,
  joined_date date,
  left_date date,
  mbti text,
  avatar_path text
);
create index if not exists members_name_idx on public.members (name);
create index if not exists members_nickname_idx on public.members (nickname);
create index if not exists members_soop_id_idx on public.members (soop_id);
create index if not exists members_elo_id_idx on public.members (elo_id);

create table if not exists public.matches (
  match_no integer primary key,
  source_order integer not null unique,
  match_date date not null,
  opponent_team text not null,
  match_format text,
  method text,
  final_result text,
  set_result text,
  score_diff text,
  funding text,
  support_amount text,
  personal_amount text,
  challenge_mission text
);
create index if not exists matches_date_idx on public.matches (match_date desc);
create index if not exists matches_opponent_idx on public.matches (opponent_team);

create table if not exists public.rounds (
  id bigint generated by default as identity primary key,
  source_order integer not null unique,
  match_no integer not null references public.matches(match_no) on update cascade on delete cascade,
  match_date date not null,
  opponent_team text,
  match_format text,
  set_name text,
  round_name text,
  our_player text,
  our_race text,
  our_tier text,
  result text,
  opponent_player text,
  opponent_race text,
  opponent_tier text,
  map_name text
);
create index if not exists rounds_match_no_idx on public.rounds (match_no);
create index if not exists rounds_date_idx on public.rounds (match_date desc);
create index if not exists rounds_our_player_idx on public.rounds (our_player);
create index if not exists rounds_opponent_player_idx on public.rounds (opponent_player);

create table if not exists public.tier_members (
  id bigint generated by default as identity primary key,
  source_order integer not null unique,
  name text,
  nickname text not null,
  soop_id text,
  elo_id integer,
  birth_date date,
  gender text,
  race text,
  tier text,
  affiliation text,
  role text,
  modified_at text,
  history text,
  started_on text,
  elo_registered text,
  tier_table_registered text,
  promoted_tier_8 text,
  promoted_tier_7 text,
  promoted_tier_6 text,
  promoted_tier_5 text,
  promoted_tier_4 text,
  promoted_tier_3 text,
  promoted_tier_2 text,
  promoted_tier_1 text,
  promoted_tier_0 text
);
create unique index if not exists tier_members_elo_id_uq
  on public.tier_members (elo_id) where elo_id is not null;
create index if not exists tier_members_nickname_idx on public.tier_members (nickname);
create index if not exists tier_members_soop_id_idx on public.tier_members (soop_id);
create index if not exists tier_members_affiliation_idx on public.tier_members (affiliation);

-- ELO 원본은 2차 이전용. migrate_to_supabase.py --include-elo 로 넣을 수 있습니다.
create table if not exists public.elo_categories (
  category_id smallint primary key,
  name text not null
);

create table if not exists public.elo_maps (
  map_id integer primary key,
  name text not null
);

create table if not exists public.elo_players (
  -- eloboard.json players의 key. 원본에서는 그냥 id처럼 보이지만 DB에서는 elo_id로 명확히 구분한다.
  elo_id integer primary key,
  name text not null,
  race text
);
create index if not exists elo_players_name_idx on public.elo_players (name);

create table if not exists public.elo_matches (
  elo_match_id bigint primary key,
  match_date date not null,
  winner_elo_id integer references public.elo_players(elo_id),
  loser_elo_id integer references public.elo_players(elo_id),
  map_id integer references public.elo_maps(map_id),
  category_id smallint not null references public.elo_categories(category_id)
);
create index if not exists elo_matches_date_idx on public.elo_matches (match_date desc);
create index if not exists elo_matches_winner_idx on public.elo_matches (winner_elo_id);
create index if not exists elo_matches_loser_idx on public.elo_matches (loser_elo_id);
create index if not exists elo_matches_map_idx on public.elo_matches (map_id);
create index if not exists elo_matches_category_idx on public.elo_matches (category_id);

-- 브라우저의 anon/authenticated 사용자가 정책 없이 직접 읽거나 쓰지 못하게 막습니다.
alter table public.settings enable row level security;
alter table public.teams enable row level security;
alter table public.members enable row level security;
alter table public.matches enable row level security;
alter table public.rounds enable row level security;
alter table public.tier_members enable row level security;
alter table public.elo_categories enable row level security;
alter table public.elo_maps enable row level security;
alter table public.elo_players enable row level security;
alter table public.elo_matches enable row level security;

-- 실시간 일정/휴방/사이트 표시 설정. 기존 calendar.json/nav.json의 운영 데이터를 Supabase로 이동한다.
create table if not exists public.calendar_events (
  id bigint primary key,
  source_order integer not null unique,
  start_date date not null,
  end_date date not null,
  event_time text,
  person text not null default '',
  description text,
  detail text,
  color text
);
create index if not exists calendar_events_date_idx on public.calendar_events (start_date, end_date);

create table if not exists public.calendar_off_air (
  off_date date not null,
  soop_id text not null,
  source_order integer not null default 0,
  primary key (off_date, soop_id)
);
create index if not exists calendar_off_air_date_idx on public.calendar_off_air (off_date, source_order);

create table if not exists public.site_config (
  config_key text primary key,
  config_value jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.calendar_events enable row level security;
alter table public.calendar_off_air enable row level security;
alter table public.site_config enable row level security;
-- 운영자가 수정하는 연혁 메타데이터. 사진 파일은 Storage(staruniv-media)에 두고 image_path만 저장한다.
create table if not exists public.history_entries (
  id text primary key,
  entry_kind text not null default 'manual' check (entry_kind in ('manual','override')),
  event_date date,
  event_type text,
  title text,
  description text,
  members jsonb not null default '[]'::jsonb,
  youtube_url text,
  image_path text,
  sort_order integer,
  hidden boolean not null default false,
  updated_at timestamptz not null default now()
);
create index if not exists history_entries_date_idx on public.history_entries (event_date desc);

alter table public.history_entries enable row level security;

-- ============================================================================
-- 관리자 인증/RLS
-- ============================================================================

-- StarUniv 관리자용 Auth/RLS 설정
-- 현재 운영 중인 Supabase 프로젝트의 SQL Editor에서 이 파일 전체를 한 번 실행하세요.
-- 실행 후 Authentication > Users 에서 관리자 계정을 만든 다음, 맨 아래 예시 INSERT로 등록합니다.

create table if not exists public.admin_users (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'admin' check (role in ('owner', 'admin')),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

alter table public.admin_users enable row level security;

-- RLS 정책 안에서 재사용하는 관리자 판별 함수.
-- SECURITY DEFINER로 admin_users 자체의 RLS 순환을 피한다.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.admin_users a
    where a.user_id = auth.uid()
      and a.is_active = true
  );
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to authenticated;

-- 로그인한 사용자는 자기 관리자 등록 상태만 읽을 수 있다.
drop policy if exists "admin_users_read_self" on public.admin_users;
create policy "admin_users_read_self"
on public.admin_users
for select
to authenticated
using (user_id = auth.uid());

grant select on public.admin_users to authenticated;

-- 운영 데이터: 관리자만 브라우저에서 CRUD 가능.
do $$
declare
  t text;
begin
  foreach t in array array['settings','teams','members','matches','rounds','tier_members','calendar_events','calendar_off_air','site_config','history_entries']
  loop
    execute format('drop policy if exists %I on public.%I', 'admins_all_' || t, t);
    execute format(
      'create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',
      'admins_all_' || t,
      t
    );
  end loop;
end $$;

grant select, insert, update, delete on public.settings, public.teams, public.members,
  public.matches, public.rounds, public.tier_members, public.calendar_events, public.calendar_off_air, public.site_config, public.history_entries to authenticated;
grant usage, select on all sequences in schema public to authenticated;

-- ELO 원본은 관리자 화면에서는 조회만 허용한다.
do $$
declare
  t text;
begin
  foreach t in array array['elo_categories','elo_maps','elo_players','elo_matches']
  loop
    execute format('drop policy if exists %I on public.%I', 'admins_read_' || t, t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (public.is_admin())',
      'admins_read_' || t,
      t
    );
  end loop;
end $$;

grant select on public.elo_categories, public.elo_maps, public.elo_players, public.elo_matches to authenticated;

-- 경기 + 세트를 한 트랜잭션으로 저장한다.
-- 기존 경기를 수정할 때는 source_order를 유지하고, 세트 목록은 전달된 내용으로 교체한다.
create or replace function public.admin_save_match(p_match jsonb, p_rounds jsonb default '[]'::jsonb)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_match_no integer;
  v_source_order integer;
  v_round_source integer;
  r jsonb;
begin
  if not public.is_admin() then
    raise exception 'admin only';
  end if;

  v_match_no := nullif(p_match->>'match_no', '')::integer;
  if v_match_no is null then
    select coalesce(max(match_no), 0) + 1 into v_match_no from public.matches;
  end if;

  v_source_order := nullif(p_match->>'source_order', '')::integer;
  if v_source_order is null then
    select coalesce(max(source_order), 0) + 1 into v_source_order from public.matches;
  end if;

  insert into public.matches (
    match_no, source_order, match_date, opponent_team, match_format, method,
    final_result, set_result, score_diff, funding, support_amount, personal_amount, challenge_mission
  ) values (
    v_match_no,
    v_source_order,
    nullif(p_match->>'match_date','')::date,
    nullif(p_match->>'opponent_team',''),
    nullif(p_match->>'match_format',''),
    nullif(p_match->>'method',''),
    nullif(p_match->>'final_result',''),
    nullif(p_match->>'set_result',''),
    nullif(p_match->>'score_diff',''),
    nullif(p_match->>'funding',''),
    nullif(p_match->>'support_amount',''),
    nullif(p_match->>'personal_amount',''),
    nullif(p_match->>'challenge_mission','')
  )
  on conflict (match_no) do update set
    source_order = excluded.source_order,
    match_date = excluded.match_date,
    opponent_team = excluded.opponent_team,
    match_format = excluded.match_format,
    method = excluded.method,
    final_result = excluded.final_result,
    set_result = excluded.set_result,
    score_diff = excluded.score_diff,
    funding = excluded.funding,
    support_amount = excluded.support_amount,
    personal_amount = excluded.personal_amount,
    challenge_mission = excluded.challenge_mission;

  delete from public.rounds where match_no = v_match_no;
  select coalesce(max(source_order), 0) into v_round_source from public.rounds;

  for r in select value from jsonb_array_elements(coalesce(p_rounds, '[]'::jsonb))
  loop
    v_round_source := v_round_source + 1;
    insert into public.rounds (
      source_order, match_no, match_date, opponent_team, match_format,
      set_name, round_name, our_player, our_race, our_tier, result,
      opponent_player, opponent_race, opponent_tier, map_name
    ) values (
      v_round_source,
      v_match_no,
      nullif(coalesce(r->>'match_date', p_match->>'match_date'),'')::date,
      nullif(coalesce(r->>'opponent_team', p_match->>'opponent_team'),''),
      nullif(coalesce(r->>'match_format', p_match->>'match_format'),''),
      nullif(r->>'set_name',''),
      nullif(r->>'round_name',''),
      nullif(r->>'our_player',''),
      nullif(r->>'our_race',''),
      nullif(r->>'our_tier',''),
      nullif(r->>'result',''),
      nullif(r->>'opponent_player',''),
      nullif(r->>'opponent_race',''),
      nullif(r->>'opponent_tier',''),
      nullif(r->>'map_name','')
    );
  end loop;

  return v_match_no;
end;
$$;

revoke all on function public.admin_save_match(jsonb, jsonb) from public;
grant execute on function public.admin_save_match(jsonb, jsonb) to authenticated;

